    /**
     * Sets the sheet's default grade (null for blank: A), one of the grades: the grade the quick-add bar gives a new
     * person and an import line with a blank grade uses. Refused for anything else. Changing it changes no one. Not
     * dated.
     */
    @Transactional
    public Sheet setDefaultGrade(String by, String sheetId, String grade) {
        String value = grade == null || grade.isBlank() ? null : grade.strip();
        if (value != null && !value.matches("[ABC]")) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "The default grade must be A, B or C.");
        }
        Sheet sheet = sheets.lock(sheetId);
        sheet.setDefaultGrade(value);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=default-grade value="
                + (value == null ? "" : value));
        return saved;
    }

    /**
     * Retires the grade, one of the grades not yet retired: it can no longer be given to a new person or chosen in an
     * edit, while the people on it keep it. Refused for anything else. Not dated.
     */
    @Transactional
    public Sheet retireGrade(String by, String sheetId, String grade) {
        String value = grade == null ? "" : grade.strip();
        if (!value.matches("[ABC]")) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "The grade must be A, B or C.");
        }
        Sheet sheet = sheets.lock(sheetId);
        if (sheet.isGradeRetired(value)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Grade " + value + " is already retired.");
        }
        sheet.retireGrade(value);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + by + " grade=" + value);
        return saved;
    }

    /**
     * Sets the sheet's escalation gap (null for blank: off): reminding a claim whose previous reminder was at least
     * these many days before the sheet's today escalates it. Not dated.
     */
    @Transactional
    public Sheet setEscalateAfter(String by, String sheetId, Integer days) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setEscalateAfter(days);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=escalate-after value="
                + (days == null ? "" : days.toString()));
        return saved;
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody GraceDaysForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setGraceDays(user, sheetId, form.value()));
    }

    @PutMapping("/settings/proof-kinds")
    public SettingsView setProofKinds(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody ProofKindsForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setProofKinds(user, sheetId, form.value()));
    }

    /** Retires the grade: it can no longer be given to a new person or chosen in an edit. */
    @PostMapping("/grades/{grade}/retire")
    public SettingsView retireGrade(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Size(max = 10) String grade, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.retireGrade(user, sheetId, grade));
    }

    @PutMapping("/settings/default-grade")
    public SettingsView setDefaultGrade(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody DefaultGradeForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setDefaultGrade(user, sheetId, form.value()));
    }
  }

  async setDefaultGrade(sheet: string, value: string | null): Promise<void> {
    const s = await firstValueFrom(
      this.http.put<SettingsView>(`/api/sheets/${encodeURIComponent(sheet)}/settings/default-grade`, { value }),
    );
    if (this.session.sheetId() === sheet) this.show(s);
  }

  async retireGrade(sheet: string, grade: string): Promise<void> {
    const s = await firstValueFrom(
