    @Transactional
    public void move(String by, String sheetId, Long id, boolean up) {
        sheets.lock(sheetId);
        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
        int at = -1;
        for (int i = 0; i < listed.size(); i++) {
